#include <bits/stdc++.h>
using namespace std;

/**
 * Variant 2: Using fast I/O with cin/cout
 */

struct InputReader {
    std::istream& in;
    InputReader(std::istream& inStream) : in(inStream) {}
    std::string next() {
        std::string s;
        while (!(in >> s)) {
            // skip
        }
        return s;
    }
    int nextInt() {
        int x;
        in >> x;
        return x;
    }
};

struct LuckyTickets {
    const int MOD = 998244353;

    void solve(int testNumber, InputReader& in, std::ostream& out) {
        int N = 0, k = 0;
        try {
            N = in.nextInt();
            k = in.nextInt();
        } catch (...) {
            // handle exception if needed
        }
        std::vector<long long> dig(11, 0);
        for (int i = 0; i < k; i++) {
            try {
                int val = in.nextInt();
                dig[10 - val] = 1;
            } catch (...) {
                // handle exception if needed
            }
        }
        int power = N / 2;
        std::vector<long long> res(1, 1);
        while (power > 0) {
            if (power & 1) {
                res = convoluteSimply(res, dig, MOD, 3);
            }
            dig = convoluteSimply(dig, dig, MOD, 3);
            power >>= 1;
        }
        long long output = 0;
        for (auto val : res) {
            output += val * val;
            output %= MOD;
        }
        out << output << "\n";
    }

    static std::vector<long long> convoluteSimply(const std::vector<long long>& a, const std::vector<long long>& b, int P, int g) {
        int m = std::max(2, 1 << (32 - __builtin_clz(std::max((int)a.size(), (int)b.size()) - 1)) << 2);
        std::vector<long long> fa = nttmb(a, m, false, P, g);
        std::vector<long long> fb;
        if (&a == &b) {
            fb = fa;
        } else {
            fb = nttmb(b, m, false, P, g);
        }
        for (int i = 0; i < m; i++) {
            fa[i] = fa[i] * fb[i] % P;
        }
        return nttmb(fa, m, true, P, g);
    }

    static std::vector<long long> nttmb(const std::vector<long long>& src, int n, bool inverse, int P, int g) {
        std::vector<long long> dst(src);
        int h = 31 - __builtin_clz(n);
        long long K = (long long)1 << (h + 1);
        int H = h + 1;
        long long M = (long long)K * K / P;
        std::vector<int> wws(1 << (h));
        long long dw = inverse ? pow_mod(g, P - 1 - (P - 1) / n, P) : pow_mod(g, (P - 1) / n, P);
        long long w = (1LL << 32) % P;
        for (int k = 0; k < (1 << (h)); k++) {
            wws[k] = (int)w;
            w = modh(w * dw, M, H, P);
        }
        long long J = invl(P, (1LL << 32));
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < (1 << i); j++) {
                for (int k = 0, s = j << (h - i), t = s | (1 << (h - i - 1)); k < (1 << (h - i - 1)); k++, s++, t++) {
                    long long u = (dst[s] - dst[t] + 2 * P) * wws[k] % P;
                    dst[s] = (dst[s] + dst[t]) % P;
                    long long Q = ((u & 0xFFFFFFFF) * J) >> 32;
                    dst[t] = (u >> 32) - Q * P + P;
                }
            }
            if (i < h - 1) {
                for (int k = 0; k < (1 << (h - i - 2)); k++) wws[k] = wws[k * 2];
            }
        }
        for (int i = 0; i < n; i++) {
            if (dst[i] >= P) dst[i] -= P;
        }
        for (int i = 0; i < n; i++) {
            int rev = __builtin_bitreverse(i) >> (32 - h);
            if (i < rev) {
                long long d = dst[i];
                dst[i] = dst[rev];
                dst[rev] = d;
            }
        }
        if (inverse) {
            long long in = invl(n, P);
            for (int i = 0; i < n; i++) dst[i] = modh(dst[i] * in, M, H, P);
        }
        return dst;
    }

    static long long modh(long long a, long long M, int h, int mod) {
        long long r = a - ((M * ((a & 0x7FFFFFFF))) >> 31) - (M * (a >> 31) >> (h - 31)) * mod;
        return r < mod ? r : r - mod;
    }

    static long long pow_mod(long long a, long long n, long long mod) {
        long long ret = 1;
        while (n > 0) {
            if (n & 1) ret = ret * a % mod;
            a = a * a % mod;
            n >>= 1;
        }
        return ret;
    }

    static long long invl(long long a, long long mod) {
        long long b = mod, p = 1, q = 0;
        while (b > 0) {
            long long c = a / b;
            long long d = a;
            a = b;
            b = d % b;
            d = p;
            p = q;
            q = d - c * q;
        }
        return p < 0 ? p + mod : p;
    }
};

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    InputReader in(std::cin);
    LuckyTickets solver;
    solver.solve(1, in, std::cout);
    return 0;
}

